from pathlib import Path
import re,colorsys
root=Path('/workspace/lunch-match'); p=root/'app/globals.css'; css=p.read_text()
# Convert the original green family to the requested orange family, including pale surfaces.
def recolor(m):
    value=m.group()[1:]; base=value[:6]
    if len(base)!=6:return m.group()
    r,g,b=[int(base[i:i+2],16)/255 for i in (0,2,4)]
    h,l,s=colorsys.rgb_to_hls(r,g,b)
    if 0.14<h<0.52 and s>.06:
        rgb=colorsys.hls_to_rgb(.044,l,min(s*1.15,.9))
        return '#'+''.join(f'{round(c*255):02x}' for c in rgb)+value[6:]
    return m.group()
css=re.sub(r'#[0-9a-fA-F]{6}(?:[0-9a-fA-F]{2})?\b',recolor,css)
